windowclass.script:
function onClickDown(button, x, y)
				self.bringToFront();
			end

			function onInit()
				if Session.IsHost then
					makeStatTagsPublic();
				end

				if stattag_iadd then
					stattag_iadd.setVisible(Session.IsHost);
				end
			end

			function makeStatTagsPublic()
				local nodeList = DB.createNode("stattagg_list");
				if not nodeList then
					return;
				end

				nodeList.setPublic(true);

				for _, nodeEntry in pairs(DB.getChildren(nodeList)) do
					nodeEntry.setPublic(true);
				end
			end

buttonfield.script:
local bThreatsMinimized = false;

					local aHideControls = {
						"threat_list",
						"threat_list_iadd",

					};

					function setThreatsControlsVisible(bVisible)
						for _, sControl in ipairs(aHideControls) do
							if window[sControl] and window[sControl].setVisible then
								window[sControl].setVisible(bVisible);
							end
						end
					end

					function onButtonPress()
						bThreatsMinimized = not bThreatsMinimized;

						setThreatsControlsVisible(not bThreatsMinimized);

						if bThreatsMinimized then
							window.setSize(200, 50);
						else
							window.setSize(300, 300);
						end
					end
